    private LinearLayout root,header,bottom;private FrameLayout content;
    private long wallpaperVersion;private int tab=0,renderedTab=0,generation=0,pageNumber=0;private boolean historyView=false,sourceView=false,profileView=false,renderedProfileView=false;private boolean loading,more,firstResume=true;private final int[] scrollState=new int[6];
