    private GridView grid;private CatalogAdapter adapter;private TextView summary;private EditText search;private LinearLayout searchPanel;private CalendarScreen calendarScreen;private final View[] screenCache=new View[5];private final String[] screenKeys=new String[5];private final ArrayList<Future<?>> uiTasks=new ArrayList<>();private Future<?> catalogFuture;private final Handler handler=new Handler(Looper.getMainLooper());private Runnable searchTask;
    @Override public void onCreate(Bundle b){super.onCreate(b);if(!Ui.allow(this))return;if(b!=null){tab=b.getInt("tab",0);profileView=b.getBoolean("profile",false);selectedSource=b.getString("source","yoru");if(selectedSource.equals("all"))selectedSource="yoru";query=b.getString("query","");bucket=b.getString("bucket","");filter.genre=b.getString("genre","");filter.genreName=b.getString("genreName","");filter.year=b.getString("year","");filter.type=b.getString("type","");filter.status=b.getString("status","");filter.sort=b.getString("sort","RATING_DESC");filter.season=b.getString("season","");int[] saved=b.getIntArray("scroll");if(saved!=null)System.arraycopy(saved,0,scrollState,0,Math.min(saved.length,scrollState.length));}root=Ui.base(this);wallpaperVersion=YoruApp.app().store.wallpaperVersion();header=Ui.row(this);header.setPadding(Ui.dp(this,18),Ui.dp(this,13),Ui.dp(this,18),Ui.dp(this,13));ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.ic_yoru);header.addView(logo,Ui.lp(this,36,36));TextView brand=Ui.text(this,"YORU.",25,Ui.TEXT,true);LinearLayout.LayoutParams bp=Ui.lp(this,0,-2);bp.weight=1;bp.leftMargin=Ui.dp(this,9);header.addView(brand,bp);Ui.gap(header,Ui.iconButton(this,"search","Найти аниме",()->{profileView=false;tab=1;render();search.requestFocus();((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(search,InputMethodManager.SHOW_IMPLICIT);}),38,38,0);Ui.gap(header,Ui.iconButton(this,"settings","Настройки",()->{profileView=true;render();}),38,38,8);root.addView(header,Ui.lp(this,-1,-2));content=this instanceof WallpaperPreviewActivity?new WallpaperPreviewContent(this):new FrameLayout(this);root.addView(content,new LinearLayout.LayoutParams(-1,0,1));bottom=Ui.row(this);bottom.setPadding(Ui.dp(this,9),Ui.dp(this,5),Ui.dp(this,9),Ui.dp(this,5));bottom.setBackgroundColor(Ui.SURFACE);root.addView(bottom,Ui.lp(this,-1,64));if(this instanceof WallpaperPreviewActivity){if(b==null)tab=Math.max(0,Math.min(4,getIntent().getIntExtra("previewTab",0)));header.removeAllViews();header.addView(Ui.iconButton(this,"back","К настройке обоев",this::finish),Ui.lp(this,48,48));header.addView(Ui.text(this,"Предпросмотр обоев",18,Ui.TEXT,true));}if(getIntent().getBooleanExtra("openDownloads",false)){tab=3;profileView=false;}if(b==null&&getIntent().hasExtra("genreName")){tab=1;selectedSource="shikimori";String id=getIntent().getStringExtra("genreId");if("shikimori".equals(getIntent().getStringExtra("genreSource"))&&id!=null&&id.matches("[1-9][0-9]{0,8}")){filter.genre=id;filter.genreName=getIntent().getStringExtra("genreName");}}render();if(b==null&&getIntent().hasExtra("genreName")&&filter.genre.isEmpty())selectGenre(getIntent().getStringExtra("genreName"));}
    @Override protected void onResume(){super.onResume();resumed=true;handler.removeCallbacks(catalogClock);handler.postDelayed(catalogClock,60000L);if(root!=null&&wallpaperVersion!=YoruApp.app().store.wallpaperVersion()){wallpaperVersion=YoruApp.app().store.wallpaperVersion();WallpaperStyle.apply(this,root);}if(firstResume){firstResume=false;return;}YoruApp.app().discovery.execute(()->{try{if(YoruApp.app().store.takeUpdatePulse())EpisodeUpdateReceiver.schedule(this);}catch(Exception ignored){}});if(content!=null&&!profileView&&!historyView&&!sourceView&&(tab==0||tab==2))render();if(resumeCatalog){resumeCatalog=false;if(tab==1&&!profileView&&!historyView&&!sourceView)loadCatalog(resumeCatalogReset||pageNumber==0);}}
    private void render(){rememberScroll();cancelUiTasks();sourceView=false;historyView=false;generation++;loading=false;navigation();if(profileView){content.removeAllViews();content.addView(new ProfileScreen(this,this::profileAction),new FrameLayout.LayoutParams(-1,-1));restoreScroll();renderedTab=tab;renderedProfileView=profileView;WallpaperStyle.refreshSurfaces(root);return;}String key=screenKey(tab);if(screenCache[tab]!=null&&key.equals(screenKeys[tab])){content.removeAllViews();attach(screenCache[tab]);if(tab==4&&calendarScreen!=null)calendarScreen.quickShow();restoreScroll();renderedTab=tab;renderedProfileView=profileView;WallpaperStyle.refreshSurfaces(root);return;}content.removeAllViews();if(tab==0)home();else if(tab==1)catalogue();else if(tab==2)library(false);else if(tab==3)screen("Загрузки",()->new DownloadsScreen(this));else if(tab==4)screen("Календарь",this::calendarView);capture(tab,key);restoreScroll();renderedTab=tab;renderedProfileView=profileView;WallpaperStyle.refreshSurfaces(root);}
    private void selectGenre(String name){String source=selectedSource;int token=generation;uiTask(()->{try{String id="",canonical=name;for(String[] row:YoruApp.app().api.genres(source))if(ApiRepository.plainName(row[1]).equals(ApiRepository.plainName(name))||(row.length>2&&ApiRepository.plainName(row[2]).equals(ApiRepository.plainName(name)))){id=row[0];canonical=row[1];break;}String selected=id,selectedName=canonical;YoruApp.app().main.post(()->{if(isFinishing()||generation!=token||tab!=1||!source.equals(selectedSource))return;if(selected.isEmpty()){Ui.toast(this,"Жанр недоступен в выбранном каталоге");return;}filter=new ApiRepository.Filter();filter.genre=selected;filter.genreName=selectedName;invalidateScreen(1);loadCatalog(true);});}catch(Exception e){YoruApp.app().main.post(()->{if(!isFinishing()&&generation==token)Ui.toast(this,"Не удалось загрузить справочник жанров");});}});}
    private void navigation(){bottom.removeAllViews();String[] names={"Главная","Каталог","Коллекция","Загрузки","Календарь"},icons={"home","grid","heart","download","calendar"};for(int i=0;i<names.length;i++){final int target=i;LinearLayout cell=Ui.column(this);cell.setGravity(Gravity.CENTER);Ui.Icon icon=new Ui.Icon(this,icons[i]);boolean active=tab==i&&!profileView;icon.color=active?Ui.PURPLE:Ui.MUTED;cell.addView(icon,Ui.lp(this,31,31));String text=names[i];TextView label=Ui.text(this,text,10,active?Ui.PURPLE:Ui.MUTED,active);label.setGravity(Gravity.CENTER);Ui.space(cell,3);cell.addView(label,Ui.lp(this,-1,-2));if(active)cell.setBackground(Ui.shape(0xff2a2036,12,this));cell.setContentDescription(text);cell.setOnClickListener(v->{if(tab!=target||profileView){tab=target;profileView=false;render();}});bottom.addView(cell,new LinearLayout.LayoutParams(0,-1,1));}}

    private String screenKey(int t){if(t==1)return "catalog:"+selectedSource+":"+query+":"+filter.year+":"+filter.genre+":"+filter.type+":"+filter.status+":"+filter.sort+":"+filter.season;if(t==2)return "library:"+bucket+":"+YoruApp.app().store.libraryVersion();return "tab:"+t;}
    private void attach(View v){try{ViewParent p=v.getParent();if(p instanceof ViewGroup)((ViewGroup)p).removeView(v);}catch(Exception ignored){}content.addView(v,new FrameLayout.LayoutParams(-1,-1));}
    private void capture(int t,String key){if(t<0||t>=screenCache.length||content.getChildCount()==0)return;if(t==3)return;screenCache[t]=content.getChildAt(0);screenKeys[t]=key;}
    private void invalidateScreen(int t){if(t>=0&&t<screenCache.length){screenCache[t]=null;screenKeys[t]=null;}}
    private Future<?> uiTask(Runnable r){uiTasks.removeIf(Future::isDone);Future<?> f=YoruApp.app().ui.submit(r);uiTasks.add(f);return f;}
    private void cancelUiTasks(){for(Future<?> f:new ArrayList<>(uiTasks))if(f!=null&&!f.isDone())f.cancel(true);uiTasks.clear();if(catalogFuture!=null&&!catalogFuture.isDone())catalogFuture.cancel(true);if(searchTask!=null){handler.removeCallbacks(searchTask);searchTask=null;}catalogRefreshing=false;}
    private int slot(boolean profile,int value){return profile?5:Math.max(0,Math.min(4,value));}
    private void rememberScroll(){try{if(content==null||content.getChildCount()==0)return;View v=content.getChildAt(0);ScrollView sc=findScroll(v);int slot=slot(renderedProfileView,renderedTab);if(sc!=null)scrollState[slot]=sc.getScrollY();else if(grid!=null&&slot==1)scrollState[slot]=grid.getFirstVisiblePosition();}catch(Exception ignored){}}
    private void restoreScroll(){try{int slot=slot(profileView,tab),y=scrollState[slot];View v=content==null||content.getChildCount()==0?null:content.getChildAt(0);ScrollView sc=findScroll(v);if(sc!=null)sc.post(()->sc.scrollTo(0,y));else if(grid!=null&&slot==1)grid.post(()->grid.setSelection(Math.max(0,y)));}catch(Exception ignored){}}
    private ScrollView findScroll(View v){if(v instanceof ScrollView)return (ScrollView)v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){ScrollView found=findScroll(g.getChildAt(i));if(found!=null)return found;}}return null;}
    private interface ScreenFactory {View create();}
    private void screen(String title,ScreenFactory factory){try{content.addView(factory.create(),new FrameLayout.LayoutParams(-1,-1));}catch(Throwable e){LinearLayout col=Ui.column(this);col.setPadding(Ui.dp(this,18),Ui.dp(this,28),Ui.dp(this,18),Ui.dp(this,18));col.addView(Ui.text(this,title,28,Ui.TEXT,true));Ui.space(col,12);col.addView(Ui.text(this,"Раздел восстановлен после ошибки. Нажмите ещё раз или обновите данные.",13,Ui.MUTED,false));Ui.space(col,14);col.addView(Ui.button(this,"Повторить",true,this::render));content.addView(col,new FrameLayout.LayoutParams(-1,-1));}}
    private View calendarView(){if(calendarScreen==null)calendarScreen=new CalendarScreen(this);else calendarScreen.quickShow();return calendarScreen;}
    private LinearLayout scrolling(){ScrollView sc=new ScrollView(this);sc.setFillViewport(true);sc.setVerticalScrollBarEnabled(false);LinearLayout col=Ui.column(this);col.setPadding(Ui.dp(this,17),Ui.dp(this,13),Ui.dp(this,17),Ui.dp(this,25));sc.addView(col,new ScrollView.LayoutParams(-1,-2));content.addView(sc,new FrameLayout.LayoutParams(-1,-1));return col;}
    private void home(){content.addView(new HomeScreen(this,this::homeExtras),new FrameLayout.LayoutParams(-1,-1));}
    private void homeExtras(LinearLayout col){Ui.space(col,18);LinearLayout calendar=Ui.row(this);calendar.setPadding(Ui.dp(this,15),Ui.dp(this,16),Ui.dp(this,15),Ui.dp(this,16));calendar.setBackground(Ui.stroke(Ui.CARD,14,this));LinearLayout cw=Ui.column(this);cw.addView(Ui.text(this,"Календарь выхода",13,Ui.TEXT,true));Ui.space(cw,6);cw.addView(Ui.text(this,"Все ближайшие аниме и серии одним списком",11,Ui.MUTED,false));calendar.addView(cw,new LinearLayout.LayoutParams(0,-2,1));Ui.Icon ci=new Ui.Icon(this,"calendar");ci.color=Ui.PURPLE;calendar.addView(ci,Ui.lp(this,24,24));calendar.setOnClickListener(v->{tab=4;render();});col.addView(calendar,Ui.lp(this,-1,-2));moodBar(col);if(YoruApp.app().store.ready()){dashboardPanel(col);newEpisodesPanel(col);focusQueue(col);watchPlan(col);List<Anime> history=YoruApp.app().store.recent();if(!history.isEmpty()){Ui.space(col,25);section(col,"Продолжим?","Вся история",()->libraryHistory());HorizontalScrollView row=new HorizontalScrollView(this);row.setHorizontalScrollBarEnabled(false);LinearLayout list=Ui.row(this);history=YoruBrain.visible(history);for(Anime rowAnime:history.subList(0,Math.min(6,history.size()))){LinearLayout item=Ui.column(this);item.setPadding(0,0,Ui.dp(this,10),0);Ui.Card card=new Ui.Card(this,160);card.bind(rowAnime);JSONObject h=YoruApp.app().store.progress(rowAnime);card.setOnClickListener(v->Ui.openPlayer(this,rowAnime,h.optString("playerMode","auto"),h.optDouble("episode",1)));item.addView(card,Ui.lp(this,132,-2));TextView progress=Ui.text(this,"Серия "+(int)h.optDouble("episode",1)+" · "+Ui.time(h.optInt("time")),10,Ui.MUTED,false);item.addView(progress);list.addView(item);}row.addView(list);col.addView(row,Ui.lp(this,-1,-2));}}}



    private void dashboardPanel(LinearLayout col){Ui.space(col,18);LinearLayout card=Ui.column(this);card.setPadding(Ui.dp(this,16),Ui.dp(this,16),Ui.dp(this,16),Ui.dp(this,16));card.setBackground(Ui.stroke(Ui.CARD,16,this));card.addView(Ui.text(this,"Сейчас в YORU",16,Ui.TEXT,true));Ui.space(card,8);card.addView(Ui.text(this,YoruBrain.dashboard()+"\nОзвучки: "+YoruApp.app().store.favoriteVoiceSummary()+" · "+QualityPlus.name(YoruApp.app().store.quality()),11,Ui.MUTED,false));List<Anime> recent=YoruApp.app().store.recent();if(!recent.isEmpty()){Ui.space(card,12);TextView cont=Ui.button(this,"Продолжить просмотр",true,()->{List<Anime> rows=YoruApp.app().store.recent();if(rows.isEmpty()){tab=1;render();return;}Anime a=rows.get(0);JSONObject h=YoruApp.app().store.progress(a);Ui.openPlayer(this,a,h.optString("playerMode","yoru"),h.optDouble("episode",1));});card.addView(cont,Ui.lp(this,-1,-2));}col.addView(card,Ui.lp(this,-1,-2));}

    private void newEpisodesPanel(LinearLayout col){ArrayList<Anime> rows=YoruBrain.newEpisodes(8);if(rows.isEmpty())return;Ui.space(col,24);section(col,"Новые серии для вас","Коллекция",()->{tab=2;render();});HorizontalScrollView row=new HorizontalScrollView(this);row.setHorizontalScrollBarEnabled(false);LinearLayout list=Ui.row(this);for(Anime a:rows){LinearLayout item=Ui.column(this);item.setPadding(0,0,Ui.dp(this,10),0);Ui.Card card=new Ui.Card(this,164);card.bind(a);JSONObject h=YoruApp.app().store.progress(a);double next=Math.max(1,Math.floor(h.optDouble("episode",0))+1);card.setOnClickListener(v->Ui.openPlayer(this,a,h.optString("playerMode","yoru"),next));item.addView(card,Ui.lp(this,136,-2));String line=a.episodesLine();if(line.isEmpty())line="Продолжить";item.addView(Ui.text(this,line,10,Ui.PURPLE,false));list.addView(item);}row.addView(list);col.addView(row,Ui.lp(this,-1,-2));}
    private void focusQueue(LinearLayout col){ArrayList<Anime> rows=YoruBrain.priorities(6);if(rows.isEmpty())return;Ui.space(col,24);section(col,"Главное сейчас","Смотреть",()->{tab=1;render();});LinearLayout host=Ui.column(this);col.addView(host);renderCards(host,rows.subList(0,Math.min(6,rows.size())));}
    private void quickShelves(LinearLayout col){smartShelf(col,"Для вас","forYou","Каталог",()->{tab=1;render();});smartShelf(col,"Короткий марафон","short","Фильтры",()->{filter=new ApiRepository.Filter();filter.type="TV";tab=1;render();});smartShelf(col,"Фильмы на вечер","movies","Каталог",()->{filter=new ApiRepository.Filter();filter.type="MOVIE";tab=1;render();});smartShelf(col,"Скрытые жемчужины","gems","Открыть",()->{tab=1;render();});smartShelf(col,"Сейчас выходит","ongoing","Календарь",()->{tab=4;render();});smartShelf(col,"Классика","classics","Открыть",()->{tab=1;render();});}
    private void smartShelf(LinearLayout col,String title,String kind,String action,Runnable click){ArrayList<Anime> rows=YoruBrain.shelf(kind,8);if(rows.isEmpty())return;Ui.space(col,24);section(col,title,action,click);LinearLayout host=Ui.column(this);col.addView(host);renderCards(host,rows);}
    private void surprisePick(){Anime a=YoruBrain.surprise();if(a==null){Ui.toast(this,"Сначала откройте каталог");return;}Ui.openDetails(this,a);}
    private void watchPlan(LinearLayout col){List<Anime> plan=YoruApp.app().store.watchQueue();if(plan.isEmpty())return;Ui.space(col,25);section(col,"План вечера","Очистить",()->{YoruApp.app().store.clearWatchQueue();render();});HorizontalScrollView row=new HorizontalScrollView(this);row.setHorizontalScrollBarEnabled(false);LinearLayout list=Ui.row(this);for(Anime a:plan.subList(0,Math.min(10,plan.size()))){LinearLayout item=Ui.column(this);item.setPadding(0,0,Ui.dp(this,10),0);Ui.Card card=new Ui.Card(this,160);card.bind(a);JSONObject h=YoruApp.app().store.progress(a);card.setOnClickListener(v->Ui.openPlayer(this,a,h.optString("playerMode","yoru"),h.optDouble("episode",1)));item.addView(card,Ui.lp(this,132,-2));item.addView(Ui.text(this,"Продолжить · серия "+Ui.number(h.optDouble("episode",1)),10,Ui.PURPLE,false));list.addView(item);}row.addView(list);col.addView(row,Ui.lp(this,-1,-2));}
    private void moodBar(LinearLayout col){Ui.space(col,18);HorizontalScrollView row=new HorizontalScrollView(this);row.setHorizontalScrollBarEnabled(false);LinearLayout chips=Ui.row(this);for(String mood:new String[]{"Уютное","Экшен","Романтика","Короткое"}){TextView chip=Ui.chip(this,mood,false,()->showMood(mood));LinearLayout.LayoutParams p=Ui.lp(this,-2,-2);p.rightMargin=Ui.dp(this,7);chips.addView(chip,p);}row.addView(chips);col.addView(row,Ui.lp(this,-1,-2));}
    private void showMood(String mood){ArrayList<Anime> rows=YoruApp.app().store.mood(mood);if(rows.isEmpty()){query=mood;tab=1;render();return;}ScrollView sc=new ScrollView(this);LinearLayout col=Ui.column(this);sc.addView(col);sc.setLayoutParams(new LinearLayout.LayoutParams(-1,Ui.dp(this,430)));for(Anime a:rows.subList(0,Math.min(20,rows.size()))){LinearLayout line=Ui.row(this);line.setPadding(Ui.dp(this,12),Ui.dp(this,10),Ui.dp(this,12),Ui.dp(this,10));line.setBackground(Ui.stroke(Ui.CARD,13,this));line.addView(Ui.text(this,YoruBrain.title(a),13,Ui.TEXT,true),new LinearLayout.LayoutParams(0,-2,1));Ui.Icon icon=new Ui.Icon(this,"play");icon.color=Ui.PURPLE;line.addView(icon,Ui.lp(this,22,22));Ui.press(line);line.setOnClickListener(v->Ui.openDetails(this,a));col.addView(line,Ui.lp(this,-1,-2));Ui.space(col,8);}Ui.custom(this,mood,sc,"Готово",null,null,null,null);}
    private void recommendations(LinearLayout col){JSONArray genres=YoruApp.app().store.stats().optJSONArray("genres");if(genres==null||genres.length()==0)return;String g=genres.optString(0,"");if(g.isEmpty())return;ArrayList<Anime> rows=new ArrayList<>();for(Anime a:YoruApp.app().api.seed())for(String genre:a.genres)if(genre.equalsIgnoreCase(g)&&YoruBrain.visible(a)){rows.add(a);break;}if(rows.isEmpty())return;Ui.space(col,25);section(col,"Вам может понравиться","Каталог",()->{query=g;tab=1;render();});LinearLayout host=Ui.column(this);col.addView(host);renderCards(host,rows.subList(0,Math.min(8,rows.size())));}
    private void seasonal(LinearLayout col){Ui.space(col,25);section(col,"Сезон сейчас","Календарь",()->{tab=4;render();});LinearLayout host=Ui.column(this);col.addView(host);renderCards(host,YoruApp.app().api.seed().subList(0,Math.min(8,YoruApp.app().api.seed().size())));ApiRepository.Filter f=new ApiRepository.Filter();f.year=String.valueOf(Calendar.getInstance().get(Calendar.YEAR));f.season=currentSeason();f.status="ongoing";final int gen=generation;uiTask(()->{try{Anime.Page p=YoruApp.app().api.catalog("shikimori","",1,f);YoruApp.app().main.post(()->{if(gen==generation&&tab==0&&!isFinishing()&&!p.items.isEmpty())renderCards(host,p.items.subList(0,Math.min(8,p.items.size())));});}catch(Exception ignored){}});}
    private String currentSeason(){int m=Calendar.getInstance().get(Calendar.MONTH)+1;if(m<=2||m==12)return "winter";if(m<=5)return "spring";if(m<=8)return "summer";return "fall";}
