    private ArrayList<Anime> localCatalogPreview(String source,ApiRepository.Filter f){ArrayList<Anime> out=new ArrayList<>();for(Anime a:YoruApp.app().api.seed())if(Anime.valid(a)&&YoruBrain.visible(a)&&localFilter(a,f))out.add(a);out.sort((a,b)->localCompare(a,b,f));return new ArrayList<>(out.subList(0,Math.min(24,out.size())));}
    private boolean localFilter(Anime a,ApiRepository.Filter f){if(f==null)return true;if(!f.year.isEmpty()&&a.year!=parseInt(f.year))return false;if(!f.type.isEmpty()){String t=(a.type==null?"":a.type).toLowerCase(Locale.ROOT);if(f.type.equals("MOVIE")&&!t.contains("movie")&&!t.contains("фильм"))return false;if(f.type.equals("TV")&&!t.contains("tv")&&!t.contains("тв")&&!t.contains("сериал"))return false;}if(!f.status.isEmpty()){String st=a.statusLabel().toLowerCase(Locale.ROOT);if(f.status.equals("ongoing")&&!st.contains("онго"))return false;if(f.status.equals("released")&&!st.contains("закон"))return false;if(f.status.equals("anons")&&!st.contains("анонс"))return false;}if(!f.genre.isEmpty()){String g=String.join(" ",a.genres).toLowerCase(Locale.ROOT);String want=f.genre.equals("1")?"экшен":f.genre.equals("4")?"комед":f.genre.equals("10")?"фэнт":f.genre.equals("22")?"роман":"";if(!want.isEmpty()&&!g.contains(want))return false;}return true;}
    private int localCompare(Anime a,Anime b,ApiRepository.Filter f){if(f!=null&&"NAME".equals(f.sort))return YoruBrain.title(a).compareToIgnoreCase(YoruBrain.title(b));return Integer.compare(localSortScore(b,f),localSortScore(a,f));}
    private int localSortScore(Anime a,ApiRepository.Filter f){String sort=f==null?"":f.sort;if("NAME".equals(sort))return -YoruBrain.title(a).toLowerCase(Locale.ROOT).hashCode();int r=0;if("YEAR_DESC".equals(sort))r+=Math.max(0,a.year)*100;else r+=(int)Math.round(a.score*1000);if(a.ongoing())r+=80;return r;}
    private int parseInt(String v){try{return Integer.parseInt(v);}catch(Exception e){return 0;}}
    private ArrayList<Anime> localSuggestions(String q){LinkedHashMap<String,Anime> found=new LinkedHashMap<>();String needle=ApiRepository.plainName(q);if(needle.length()<1)return new ArrayList<>();ArrayList<Anime> pool=new ArrayList<>();pool.addAll(YoruApp.app().store.recent());pool.addAll(YoruApp.app().store.favorites());pool.addAll(YoruApp.app().api.seed());for(Anime a:pool){if(!Anime.valid(a)||!YoruBrain.visible(a)||found.containsKey(a.key()))continue;String hay=ApiRepository.plainName(a.title+" "+a.original+" "+a.alias+" "+String.join(" ",a.genres)+" "+YoruApp.app().store.note(a)+" "+YoruApp.app().store.tags(a));if(hay.contains(needle))found.put(a.key(),a);}ArrayList<Anime> out=new ArrayList<>(found.values());out.sort((a,b)->Integer.compare(searchRank(b,needle),searchRank(a,needle)));return new ArrayList<>(out.subList(0,Math.min(10,out.size())));}
    private int searchRank(Anime a,String needle){String title=ApiRepository.plainName(a.title),orig=ApiRepository.plainName(a.original),all=ApiRepository.plainName(a.title+" "+a.original+" "+a.alias);int r=0;if(title.equals(needle)||orig.equals(needle))r+=10000;else if(title.startsWith(needle)||orig.startsWith(needle))r+=6500;else if(all.contains(needle))r+=3000;r+=Math.max(0,Math.min(3000,a.year));if(a.ongoing())r+=200;if(a.score>0)r+=(int)(a.score*20);return r;}
    private void catalogueReplace(){invalidateScreen(1);content.removeAllViews();loading=false;catalogue();capture(1,screenKey(1));}
private void refreshCatalogQuietly(){
        if(this instanceof WallpaperPreviewActivity||!resumed||tab!=1||profileView||loading||catalogRefreshing||catalogScrollState!=0||System.currentTimeMillis()-catalogUpdated<3600000L)return;
        int token=generation;String source=selectedSource,text=query;ApiRepository.Filter selectedFilter=filter;catalogRefreshing=true;
        refreshFuture=uiTask(()->{try{Anime.Page fresh=YoruApp.app().api.catalog(source,text,1,selectedFilter);YoruApp.app().main.post(()->{if(token!=generation)return;catalogRefreshing=false;if(!resumed||token!=generation||tab!=1||loading||catalogScrollState!=0||grid==null)return;int first=grid.getFirstVisiblePosition();String anchor=first>=0&&first<catalog.size()?catalog.get(first).key():"";int offset=grid.getChildCount()>0?grid.getChildAt(0).getTop():0;LinkedHashMap<String,Anime> merged=new LinkedHashMap<>();for(Anime anime:fresh.items)if(YoruBrain.visible(anime))merged.put(anime.key(),anime);if(fresh.more)for(Anime anime:catalog)if(!merged.containsKey(anime.key()))merged.put(anime.key(),anime);if(pageNumber<=1||!fresh.more){pageNumber=1;more=fresh.more;}catalog.clear();catalog.addAll(merged.values());catalogUpdated=System.currentTimeMillis();adapter.notifyDataSetChanged();if(!anchor.isEmpty())for(int i=0;i<catalog.size();i++)if(anchor.equals(catalog.get(i).key())){int position=i;grid.post(()->{if(token==generation&&tab==1)grid.smoothScrollToPositionFromTop(position,offset,0);});break;}summary.setText("Показано: "+catalog.size()+(more?" · листайте дальше":""));});}catch(Exception error){YoruApp.app().main.post(()->{if(token==generation)catalogRefreshing=false;});}});
        if(refreshFuture.isCancelled())catalogRefreshing=false;
    }
    private void loadCatalog(boolean reset){if(adapter==null||summary==null)return;if(reset&&searchTask!=null){handler.removeCallbacks(searchTask);searchTask=null;}if(reset&&catalogFuture!=null&&!catalogFuture.isDone()){catalogFuture.cancel(true);loading=false;}if(loading&&!reset)return;String q=query==null?"":query.trim().replaceAll("\\s+"," ");query=q;String source=selectedSource;ApiRepository.Filter f=filter;if(screenCache[1]!=null)screenKeys[1]=screenKey(1);if(reset){generation++;pageNumber=0;catalog.clear();more=false;if(q.length()>=1)catalog.addAll(localSuggestions(q));else catalog.addAll(localCatalogPreview(source,filter));adapter.notifyDataSetChanged();}loading=true;int gen=generation,requested=pageNumber+1;summary.setOnClickListener(null);summary.setText(reset?(catalog.isEmpty()?"":""):"Ещё аниме…");catalogFuture=uiTask(()->{try{if(Thread.currentThread().isInterrupted())return;Anime.Page p=YoruApp.app().api.catalog(source,q,requested,f);if(Thread.currentThread().isInterrupted())return;YoruApp.app().main.post(()->{if(gen!=generation||tab!=1||isFinishing())return;loading=false;pageNumber=requested;more=p.more;if(requested==1)catalogUpdated=System.currentTimeMillis();HashSet<String> ids=new HashSet<>();if(reset)catalog.clear();for(Anime a:catalog)ids.add(a.key());for(Anime a:p.items)if(YoruBrain.visible(a)&&ids.add(a.key()))catalog.add(a);adapter.notifyDataSetChanged();String prefix=p.total>=0?"Найдено: "+p.total+" · ":q.isEmpty()&&YoruApp.app().api.countOf(source)>0?"В базе: "+YoruApp.app().api.countOf(source)+" · ":"";if(p.note!=null&&!p.note.isEmpty())prefix=p.note+" · "+prefix;summary.setText(prefix+"Показано: "+catalog.size()+(p.more?" · листайте дальше":""));if(catalog.isEmpty())summary.setText(q.isEmpty()?"Пока пусто. Нажмите для повтора.":"Ничего не найдено. Попробуйте другое название.");});}catch(Exception e){YoruApp.app().main.post(()->{if(gen!=generation||tab!=1||isFinishing())return;loading=false;more=false;if(catalog.isEmpty()&&source.equals("anilibria")&&q.isEmpty())catalog.addAll(YoruApp.app().api.seed());adapter.notifyDataSetChanged();summary.setText(catalog.isEmpty()?"Не удалось подключиться. Нажмите для повтора.":"");summary.setOnClickListener(v->loadCatalog(true));});}});if(catalogFuture.isCancelled()){loading=false;summary.setText("Очередь занята. Нажмите для повтора.");summary.setOnClickListener(v->loadCatalog(true));}}
    private final class CatalogAdapter extends BaseAdapter {public int getCount(){return catalog.size();}public Object getItem(int p){return catalog.get(p);}public long getItemId(int p){return p;}public View getView(int p,View old,android.view.ViewGroup parent){int cols=getResources().getConfiguration().screenWidthDp>=650?3:2;Ui.Card card=old instanceof Ui.Card?(Ui.Card)old:new Ui.Card(MainActivity.this,(getResources().getConfiguration().screenWidthDp/cols-23)*3/2);Anime selected=catalog.get(p);card.bind(selected);card.setOnClickListener(view->{YoruApp.app().store.rememberSearchResult(query,selected);Ui.openDetails(MainActivity.this,selected);});return card;}}
    private void filters(){String filterSource=(selectedSource.equals("shikimori")||selectedSource.equals("yummy")||selectedSource.equals("anilibria"))?selectedSource:"shikimori";LinearLayout c=Ui.column(this);c.setPadding(Ui.dp(this,4),0,Ui.dp(this,4),0);String[][] genreItems=genresFor(filterSource);ArrayList<String> genreLabels=new ArrayList<>(),genreIds=new ArrayList<>();for(String[] item:genreItems){genreIds.add(item[0]);genreLabels.add(item[1]);}GenrePicker genre=new GenrePicker(this,genreItems,filter.genre,filter.genreName);c.addView(genre,Ui.lp(this,-1,-2));ArrayList<String> ys=new ArrayList<>();ys.add("Все годы");for(int y=Calendar.getInstance().get(Calendar.YEAR)+1;y>=1970;y--)ys.add(String.valueOf(y));Spinner year=spinner(c,"Год",ys.toArray(new String[0]),filter.year.isEmpty()?0:ys.indexOf(filter.year));String[] kinds={"Любой формат","ТВ","Фильм","ONA","OVA","Спешл"},values={"","TV","MOVIE","ONA","OVA","SPECIAL"};Spinner type=spinner(c,"Формат",kinds,Arrays.asList(values).indexOf(filter.type));String[] statusLabels={"Любой статус","Выходит","Завершён","Анонс"},statusValues={"","ongoing","released","anons"};Spinner status=spinner(c,"Статус",statusLabels,Arrays.asList(statusValues).indexOf(filter.status));String[] sortLabels={"По рейтингу","Популярные","Сначала новые","По алфавиту"},sortValues={"RATING_DESC","POPULARITY","YEAR_DESC","NAME"};Spinner sort=spinner(c,"Порядок",sortLabels,Arrays.asList(sortValues).indexOf(filter.sort));Dialog genreDialog=Ui.custom(this,"Подберите историю",c,"Применить",()->{ApiRepository.Filter f=new ApiRepository.Filter();f.genre=genre.selectedId();f.genreName=genre.selectedName();f.year=year.getSelectedItemPosition()==0?"":ys.get(year.getSelectedItemPosition());f.type=values[type.getSelectedItemPosition()];f.status=statusValues[status.getSelectedItemPosition()];f.sort=sortValues[sort.getSelectedItemPosition()];filter=f;invalidateScreen(1);loadCatalog(true);},"Сбросить",()->{filter=new ApiRepository.Filter();invalidateScreen(1);loadCatalog(true);},"@close");Future<?> genreLoad=uiTask(()->{try{String[][] available=YoruApp.app().api.genres(filterSource);YoruApp.app().main.post(()->{if(genreDialog.isShowing()&&!isFinishing())genre.replace(available);});}catch(Exception e){YoruApp.app().main.post(()->{if(genreDialog.isShowing()&&!isFinishing())Ui.toast(this,"Полный список жанров сейчас недоступен");});}});genreDialog.setOnDismissListener(dialog->genreLoad.cancel(true));}
    private String[][] genresFor(String source){if(source.equals("shikimori"))return new String[][]{{"","Все жанры"},{"1","Экшен"},{"2","Приключения"},{"4","Комедия"},{"7","Детектив"},{"8","Драма"},{"10","Фэнтези"},{"22","Романтика"},{"24","Фантастика"},{"30","Спорт"},{"36","Повседневность"}};if(source.equals("yummy"))return new String[][]{{"","Все жанры"},{"63","Экшен"},{"32","Приключения"},{"16","Комедия"},{"14","Детектив"},{"15","Драма"},{"42","Фэнтези"},{"33","Романтика"},{"37","Фантастика"},{"86","Повседневность"}};if(source.equals("anilibria"))return new String[][]{{"","Все жанры"},{"14","Экшен"},{"27","Приключения"},{"1","Комедия"},{"8","Драма"},{"29","Фэнтези"},{"11","Романтика"}};return new String[][]{{"","Все жанры"}};}
    private Spinner spinner(LinearLayout col,String title,String[] values,int initial){col.addView(Ui.text(this,title,11,Ui.MUTED,false));Spinner s=new Spinner(this);ArrayAdapter<String> a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,values);s.setAdapter(a);s.setSelection(Math.max(0,initial));col.addView(s,Ui.lp(this,-1,45));Ui.space(col,8);return s;}
    private void libraryHistory(){historyView=true;generation++;content.removeAllViews();library(true);}
    private void library(boolean history){LinearLayout col=scrolling();LinearLayout title=Ui.row(this);title.addView(Ui.text(this,history?"История":"Моя коллекция",25,Ui.TEXT,true),new LinearLayout.LayoutParams(0,-2,1));TextView action=Ui.text(this,history?"Коллекция":"История",11,Ui.PURPLE,true);action.setOnClickListener(v->{if(history){tab=2;render();}else libraryHistory();});if(history)title.addView(action);col.addView(title);Ui.space(col,9);col.addView(Ui.text(this,history?"Продолжайте с сохранённого места.":"Ваши планы, любимые истории и личные папки.",12,Ui.MUTED,false));Ui.space(col,18);if(!history){HorizontalScrollView h=new HorizontalScrollView(this);LinearLayout chips=Ui.row(this);ArrayList<String> labels=new ArrayList<>(),values=new ArrayList<>();labels.add("Все");values.add("");for(int i=0;i<5;i++){labels.add(SecureStore.BUCKET_LABELS[i]);values.add(SecureStore.BUCKETS[i]);}for(String f:YoruApp.app().store.libraryFolders()){labels.add("Папка: "+f);values.add("folder:"+f);}for(int i=0;i<labels.size();i++){String value=values.get(i),label=labels.get(i);TextView t=Ui.button(this,label,bucket.equals(value),()->{bucket=value;invalidateScreen(2);content.removeAllViews();library(false);capture(2,screenKey(2));});LinearLayout.LayoutParams cp=Ui.lp(this,-2,-2);cp.rightMargin=Ui.dp(this,6);chips.addView(t,cp);}h.setHorizontalScrollBarEnabled(false);h.addView(chips);col.addView(h);Ui.space(col,9);if(!YoruApp.app().store.libraryFolders().isEmpty())col.addView(Ui.text(this,"Папки редактируются из карточки тайтла: В коллекцию → Папки / полки.",10,Ui.MUTED,false));Ui.space(col,17);}List<Anime> rows=YoruBrain.visible(history?YoruApp.app().store.recent():YoruApp.app().store.favorites(bucket,""));if(rows.isEmpty()){Ui.space(col,40);TextView empty=Ui.text(this,history?"Пока нет просмотров":"Здесь начнётся ваша коллекция",18,Ui.TEXT,true);empty.setGravity(Gravity.CENTER);col.addView(empty);Ui.space(col,12);col.addView(Ui.button(this,"Найти аниме",true,()->{tab=1;render();}));}else if(history){for(Anime a:rows){JSONObject progress=YoruApp.app().store.progress(a);LinearLayout line=Ui.row(this);line.setPadding(Ui.dp(this,13),Ui.dp(this,13),Ui.dp(this,13),Ui.dp(this,13));line.setBackground(Ui.stroke(Ui.CARD,13,this));ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.CENTER_CROP);line.addView(image,Ui.lp(this,48,68));YoruApp.app().images.load(image,a);LinearLayout txt=Ui.column(this);txt.setPadding(Ui.dp(this,13),0,0,0);txt.addView(Ui.text(this,YoruBrain.title(a),13,Ui.TEXT,true));Ui.space(txt,8);txt.addView(Ui.text(this,"Серия "+(int)progress.optDouble("episode",1)+" · "+Ui.time(progress.optInt("time")),11,Ui.MUTED,false));line.addView(txt,new LinearLayout.LayoutParams(0,-2,1));line.setOnClickListener(v->Ui.openPlayer(this,a,progress.optString("playerMode","auto"),progress.optDouble("episode",1)));col.addView(line);Ui.space(col,10);}}else renderCards(col,rows);}
    private void playbackSettings(){LinearLayout col=Ui.column(this);col.setPadding(Ui.dp(this,4),0,Ui.dp(this,4),0);TextView fav=Ui.text(this,"Любимые озвучки: "+YoruApp.app().store.favoriteVoiceSummary()+"\nЛюбимые озвучки будут выше в списке. Строгий режим оставляет только выбранную.",11,Ui.MUTED,false);fav.setLineSpacing(Ui.dp(this,4),1);col.addView(fav);Ui.space(col,10);VoiceOptions voices=new VoiceOptions(YoruApp.app().store.voicePreference());Spinner voice=spinner(col,"Озвучка по умолчанию",voices.names(),voices.index());Switch onlyVoice=new Switch(this);onlyVoice.setText("Показывать только выбранную озвучку");onlyVoice.setTextColor(Ui.TEXT);onlyVoice.setTextSize(13);onlyVoice.setTypeface(Ui.typeface(this,false));onlyVoice.setChecked(YoruApp.app().store.onlyPreferredVoice());col.addView(onlyVoice,Ui.lp(this,-1,50));Spinner quality=spinner(col,"Разрешение",QualityPlus.LABELS,QualityPlus.index(YoruApp.app().store.quality()));Switch next=new Switch(this);next.setText("Следующая серия автоматически");next.setTextColor(Ui.TEXT);next.setTextSize(13);next.setTypeface(Ui.typeface(this,false));next.setChecked(YoruApp.app().store.autoNext());col.addView(next,Ui.lp(this,-1,50));Switch skip=new Switch(this);skip.setText("Автопропуск заставки");skip.setTextColor(Ui.TEXT);skip.setTextSize(13);skip.setTypeface(Ui.typeface(this,false));skip.setChecked(YoruApp.app().store.autoSkipOpening());col.addView(skip,Ui.lp(this,-1,50));Spinner sleep=spinner(col,"Таймер сна",new String[]{"Выключен","15 минут","30 минут","45 минут","60 минут","90 минут"},Arrays.asList(0,15,30,45,60,90).indexOf(YoruApp.app().store.sleepTimer()));Ui.custom(this,"Просмотр",col,"Сохранить",()->{int[] sleepValues={0,15,30,45,60,90};String selectedVoice=voices.value(voice.getSelectedItemPosition());YoruApp.app().store.voicePreference(selectedVoice);if(!selectedVoice.isEmpty())YoruApp.app().store.rememberVoice(selectedVoice);YoruApp.app().store.onlyPreferredVoice(onlyVoice.isChecked()&&!selectedVoice.isEmpty());YoruApp.app().store.settings(QualityPlus.values()[quality.getSelectedItemPosition()],next.isChecked());YoruApp.app().store.smartSetting("autoSkipOpening",skip.isChecked());YoruApp.app().store.sleepTimer(sleepValues[sleep.getSelectedItemPosition()]);Ui.toast(this,"Настройки сохранены");},null,null,"Отмена");}
    private void settings(){String[] choices={"Просмотр","Внешний вид","О проекте"};Ui.choices(this,"YORU",choices,i->{switch(i){case 0:playbackSettings();break;case 1:appearanceSettings();break;default:aboutDialog();break;}});}
    private void profileAction(String action){if(action.equals("playback")){playbackSettings();return;}if(action.equals("appearance")){appearanceSettings();return;}if(action.equals("queue")){FeaturePanels.queue(this);return;}if(action.equals("smart")){FeaturePanels.smart(this);return;}if(action.equals("insights")){FeaturePanels.stats(this);return;}aboutDialog();}
    private void appearanceSettings(){LinearLayout col=Ui.column(this);col.addView(Ui.button(this,"Обои и прозрачность",false,()->startActivity(new Intent(this,WallpaperActivity.class))),Ui.lp(this,-1,-2));Ui.space(col,12);col.setPadding(Ui.dp(this,4),0,Ui.dp(this,4),0);TextView preview=Ui.text(this,"Так будет выглядеть текст в YORU",16,Ui.TEXT,true);preview.setPadding(Ui.dp(this,14),Ui.dp(this,14),Ui.dp(this,14),Ui.dp(this,14));preview.setBackground(Ui.stroke(Ui.CARD,14,this));col.addView(preview);Ui.space(col,12);TextView size=Ui.text(this,"Размер текста: "+YoruApp.app().store.fontScale()+"%",12,Ui.MUTED,true);col.addView(size);SeekBar bar=new SeekBar(this);bar.setMax(45);bar.setProgress(YoruApp.app().store.fontScale()-85);col.addView(bar,Ui.lp(this,-1,42));bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean f){int value=85+p;size.setText("Размер текста: "+value+"%");preview.setTextSize(16*value/100f);}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});Switch custom=new Switch(this);custom.setText("Использовать свой .ttf / .otf");custom.setTextColor(Ui.TEXT);custom.setTextSize(13);custom.setTypeface(Ui.typeface(this,false));custom.setChecked(YoruApp.app().store.customFont());col.addView(custom,Ui.lp(this,-1,50));TextView current=Ui.text(this,"Текущий шрифт: "+YoruApp.app().store.fontName(),11,Ui.MUTED,false);col.addView(current);Ui.space(col,10);col.addView(Ui.button(this,"Выбрать файл шрифта",false,()->{Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT);pick.addCategory(Intent.CATEGORY_OPENABLE);pick.setType("*/*");pick.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"font/ttf","font/otf","application/x-font-ttf","application/x-font-otf","application/octet-stream"});startActivityForResult(pick,103);}));Ui.space(col,8);col.addView(Ui.text(this,"Файл копируется внутрь приложения. Можно выбрать шрифт из Google Files или любого проводника.",10,Ui.MUTED,false));Ui.custom(this,"Внешний вид",col,"Сохранить",()->{YoruApp.app().store.appearance(85+bar.getProgress(),custom.isChecked(),YoruApp.app().store.fontName());Ui.toast(this,"Внешний вид обновлён");render();},"Сбросить",()->{YoruApp.app().store.appearance(100,false,"Системный");Ui.toast(this,"Внешний вид сброшен");render();},"Отмена");}
    private void aboutDialog(){Ui.message(this,"Это YORU.","Ваше пространство для любимых историй. YORU, календарь выхода, умный просмотр, офлайн, уведомления и минималистичный просмотр.\n\nВерсия "+BuildConfig.DISPLAY_VERSION+"\nМатериалы принадлежат их правообладателям.","Приятного просмотра",null);}
    private String fileName(Uri uri){String name=uri==null?"":uri.getLastPathSegment();if(name==null||name.trim().isEmpty())return "Свой шрифт";int cut=Math.max(name.lastIndexOf('/'),name.lastIndexOf(':'));if(cut>=0&&cut+1<name.length())name=name.substring(cut+1);return name.length()>48?name.substring(name.length()-48):name;}
    private void importFont(Uri uri){Ui.Progress wait=Ui.progress(this,"Импортируем шрифт…",false,null);YoruApp.app().io.execute(()->{try{File outFile=new File(getFilesDir(),"yoru-custom-font.ttf");try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(outFile)){if(in==null)throw new IOException();byte[] b=new byte[8192];int n;long total=0;while((n=in.read(b))!=-1){total+=n;if(total>8*1024*1024)throw new IOException();out.write(b,0,n);}}YoruApp.app().store.appearance(YoruApp.app().store.fontScale(),true,fileName(uri));YoruApp.app().main.post(()->{wait.dismiss();Ui.toast(this,"Шрифт применён");render();});}catch(Exception e){YoruApp.app().main.post(()->{wait.dismiss();Ui.toast(this,"Не удалось импортировать шрифт");});}});}
    @Override protected void onPause(){resumeCatalogReset=searchTask!=null||pageNumber==0;resumeCatalog=tab==1&&(loading||searchTask!=null);resumed=false;generation++;cancelUiTasks();loading=false;handler.removeCallbacks(catalogClock);if(refreshFuture!=null)refreshFuture.cancel(true);catalogRefreshing=false;rememberScroll();super.onPause();}
    @Override protected void onSaveInstanceState(Bundle out){rememberScroll();if(search!=null)query=search.getText().toString().trim();out.putInt("tab",tab);out.putBoolean("profile",profileView);out.putString("source",selectedSource);out.putString("query",query);out.putString("bucket",bucket);out.putString("genre",filter.genre);out.putString("genreName",filter.genreName);out.putString("year",filter.year);out.putString("type",filter.type);out.putString("status",filter.status);out.putString("sort",filter.sort);out.putString("season",filter.season);out.putIntArray("scroll",scrollState);super.onSaveInstanceState(out);}
    @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);if(intent.getBooleanExtra("openDownloads",false)){tab=3;profileView=false;render();}}
    @Override protected void onActivityResult(int request,int code,Intent data){super.onActivityResult(request,code,data);if(request==DocumentDownloads.REQUEST_FOLDER){DocumentDownloads.receive(this,code,data);return;}if(request==OfflineExporter.REQ_SAVE_DOCUMENT){OfflineExporter.finishDocumentSave(this,code,data);return;}if(code!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(request==103){importFont(uri);return;}}
    @Override public void onBackPressed(){rememberScroll();if(profileView){profileView=false;render();}else if(sourceView){sourceView=false;render();}else if(historyView){historyView=false;render();}else if(tab!=0){tab=0;render();}else super.onBackPressed();}
    @Override protected void onDestroy(){rememberScroll();generation++;if(searchTask!=null)handler.removeCallbacks(searchTask);handler.removeCallbacksAndMessages(null);cancelUiTasks();super.onDestroy();}
